"""Generate llms-full.txt, data/MANIFEST.sha256, and MANIFEST.sha256 deterministically."""

from __future__ import annotations

import hashlib
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]


def sha256_file(path: pathlib.Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def build_llms_full() -> None:
    parts = [
        "# llms-full.txt — Auto-Generated Context Bundle (zero-error-torus-frontier v1.0.0)\n",
        "<!-- Generated by scripts/generate_manifests.py — do not hand-edit. -->\n\n",
    ]
    for rel in ("AGENTS.md", "CLAIMS.md", "LIMITATIONS.md", "docs/build-standard.md"):
        p = ROOT / rel
        if p.exists():
            parts.append(f"\n---\n## SOURCE: {rel}\n---\n\n")
            parts.append(p.read_text(encoding="utf-8").strip() + "\n")
    (ROOT / "llms-full.txt").write_text("".join(parts), encoding="utf-8", newline="\n")


def build_manifests() -> None:
    # data/MANIFEST.sha256 (relative to repo root for `sha256sum -c data/MANIFEST.sha256`)
    data_files = [ROOT / "data" / "witnesses.json"]
    data_lines = [f"{sha256_file(p)}  {p.relative_to(ROOT).as_posix()}\n" for p in data_files]
    (ROOT / "data" / "MANIFEST.sha256").write_text("".join(data_lines), encoding="utf-8", newline="\n")

    # Root MANIFEST.sha256 covering frozen deliverables, core proofs, engines, and witnesses
    tracked: list[pathlib.Path] = []
    for pattern in (
        "VERSION",
        "LICENSE",
        "LICENSE-DOCS",
        "CITATION.cff",
        "CLAIMS.md",
        "data/witnesses.json",
        "results/lean_axioms.txt",
        "dist/Donahue_2026_zero_error_torus_frontier.pdf",
        "dist/arxiv_submission.tar.gz",
    ):
        p = ROOT / pattern
        if p.exists():
            tracked.append(p)
    for folder, ext in (
        ("lean", "*.lean"),
        ("rust/src", "*.rs"),
        ("native/include", "*.h"),
        ("native/src", "*.c"),
        ("python/torus_frontier", "*.py"),
        ("reference", "*.py"),
        ("paper", "*.tex"),
        ("paper", "*.bib"),
        ("paper/figures", "*.pdf"),
    ):
        base = ROOT / folder
        if base.exists():
            for p in sorted(base.rglob(ext)):
                if ".lake" not in p.parts and "build" not in p.parts:
                    tracked.append(p)

    # Deduplicate while keeping sorted POSIX order
    unique = sorted({p.resolve() for p in tracked}, key=lambda p: p.relative_to(ROOT).as_posix())
    lines = [f"{sha256_file(p)}  {p.relative_to(ROOT).as_posix()}\n" for p in unique]
    (ROOT / "MANIFEST.sha256").write_text("".join(lines), encoding="utf-8", newline="\n")
    print(f"Wrote llms-full.txt, data/MANIFEST.sha256 (1 file), MANIFEST.sha256 ({len(unique)} files)")


if __name__ == "__main__":
    build_llms_full()
    build_manifests()
